contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable {
        require(address(c).balance >= amount);
        uint balBefore = address(c).balance;
        bool success;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = true;
        }
        assert(success ? address(c).balance == balBefore - amount : address(c).balance == balBefore);
    }

    receive() external payable {}
}

